import{R as e,S as t,x as n}from"./vue-Bp4HY3mp.js";import{n as r}from"./app-C11vx5L5.js";var i=JSON.parse(`{"path":"/software-exam/ispm/project-stakeholder-management/comprehensive-exercises/","title":"8 综合练习 | 软考","lang":"zh-CN","frontmatter":{"title":"8 综合练习","createTime":"2026-11-22T21:20:00.000Z","permalink":"/software-exam/ispm/project-stakeholder-management/comprehensive-exercises/","outline":false,"aside":false},"readingTime":{"minutes":87.83,"words":26348},"git":{"createdTime":1795354081000},"filePathRelative":"software-exam/ispm/project-stakeholder-management/8.comprehensive-exercises.md","headers":[],"bulletin":false}`),a={name:`8.comprehensive-exercises.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t(`<div class="exam-note"><p><a id="q1" class="quiz-anchor"></a></p><p><strong>1.</strong> 根据项目干系人管理的定义，其核心作用是（ ）</p><ul><li>A．仅识别所有能影响项目的人员或组织</li><li>B．通过分析期望、制定策略，有效调动干系人参与项目决策与执行，支持项目团队工作</li><li>C．全程主导项目所有决策，确保干系人完全服从项目计划</li><li>D．仅记录干系人对项目的负面影响，规避潜在风险</li></ul><details class="quiz" data-q="1" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：O3。项目干系人管理包括识别能够影响项目或会受项目影响的人员、团体或组织，分析王系人对项目的期望和影响，制定管理策略有效调动干系人参与项目决策和执行（P5）　<span class="quiz-src">自编</span></p></details><p><a id="q2" class="quiz-anchor"></a></p><p><strong>2.</strong> 关于干系人管理的描述，不正确的是（ ）。</p><ul><li>A．干系人分析只需在项目立项时开展，以便尽早了解干系人对项目的影响</li><li>B．识别干系人的方法包含组织相关会议、专家判断、干系人分析等</li><li>C．干系人分析是系统地收集干系人各种定性和定量信息的一种方法</li><li>D．典型的项目干系人包含客户、用户、高层领导、项目团队和社会成员等</li></ul><details class="quiz" data-q="2" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：O3。为提高项目成功的概率，尽早开始识别干系人并引导干系人参与。当项目章程被批淮、项目经理被委任，以及团队开始组建之后就可以开展相关管理工作（P5）　<span class="quiz-src">自编</span></p></details><p><a id="q3" class="quiz-anchor"></a></p><p><strong>3.</strong> 根据项目干系人管理的相关要求，有效引导干系人参与项目的关键是（ ）。</p><ul><li>A．仅在项目启动阶段完成干系人识别，避免后续变更干扰</li><li>B．重视所有干系人并保持持续沟通，理解其需求期望、处理问题、管理利益冲突</li><li>C．优先满足影响力大的干系人需求，忽略影响力有限的干系人意见</li><li>D．仅在项目生命周期阶段转换时开展干系人管理活动</li></ul><details class="quiz" data-q="3" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：O3。有效引导干系人参与的关键是重视所有干系人并保持持续沟通（包括团队成员），理解他们的需求和期望、处理所发生的问题、管理利益冲突，并促进干系人参与项目决策和活动（P5）　<span class="quiz-src">自编</span></p></details><p><a id="q4" class="quiz-anchor"></a></p><p><strong>4.</strong> （ ）应作为项目目标加以识别和管理。</p><ul><li>A．干系人沟通率</li><li>B．干系人参与度</li><li>C．干系人变更数</li><li>D．干系人满意度</li></ul><details class="quiz" data-q="4" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：王系人满意度应作为项目目标加以识别和管理（P503）　<span class="quiz-src">自编</span></p></details><p><a id="q5" class="quiz-anchor"></a></p><p><strong>5.</strong> 下列时点可以不用重新开展识别干系人、排列其优先级以及引导其参与项目等相关活动（ ）</p><ul><li>A．项目进入其生命周期的不同阶段</li><li>B．当前干系人不再与项目工作有关，或者在项目的干系人群体中出现了新的干系人成员</li><li>C．组织内部或更大领域的干系人群体发生重大变化</li><li>D．项目成员小王的工作手机号发生了变化</li></ul><details class="quiz" data-q="5" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：O3。应该经常开展识别干系人、排列其优先级以及引导其参与项目等相关活动。至少要在以下时点开展这些活动：①项目进入其生命周期的不同阶段；②当前王系人不再与项目工作有关，或者在项目的干系人群体中出现了新的王系人成员：④组织内部或更大领域的干系人群体发生重大变化（P5）　<span class="quiz-src">自编</span></p></details><p><a id="q6" class="quiz-anchor"></a></p><p><strong>6.</strong> 为提高项目成功的概率，应尽早开始识别干系人并引导其参与，当（ ）被批准、（ ）被委任以及团队开始组建之后就可以开展相关管理工作；识别干系人和引导其参与的过程需要（ ）开展。</p><ul><li>A．项目章程、项目经理、迭代</li><li>B．项目管理计划、项目经理、一次性</li><li>C．项目章程、项目发起人、一次性</li><li>D．项目管理计则、项目发起人、迭代</li></ul><details class="quiz" data-q="6" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：O3。为提高项目成功的概率，尽早开始识别干系人并引导干系人参与。当项目章程被批准、项目经理被委任，以及团队开始组建之后就可以开展相关管理工作（P5）　<span class="quiz-src">自编</span></p></details><p><a id="q7" class="quiz-anchor"></a></p><p><strong>7.</strong> 以下不属于项目干系人的是（ ）。</p><ul><li>A．监管机构</li><li>B．供应商</li><li>C．实际用户</li><li>D．软考办</li></ul><details class="quiz" data-q="7" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：O3。当前新技术快速发展，“干系人”一词的外延正在扩大，从传统意义上的员工、供应商和高层管理者扩展到酒盖各式群体，包括监管机构、环保人土、金融组织、媒体，以及那些自认为是干系人的人员（他们认为自己公受项目工作或成果的影响）（P5）　<span class="quiz-src">自编</span></p></details><p><a id="q8" class="quiz-anchor"></a></p><p><strong>8.</strong> 以下关于项目干系人管理的发展趋势和新兴实践说法不正确的是（ ）</p><ul><li>A．识别所有干系人，而非在限定范围内。</li><li>B．确保所有团队成员都涉及引导干系人参与的活动。</li><li>C．定期审查干系人群体，需要与整体项目风险的审查工作并行开展。</li><li>D．关注干系人有效参与程度的正面与负面价值。</li></ul><details class="quiz" data-q="8" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：项目干系人管理的发展趋势和新兴实践主要包括：●识别所有干系人，而非在限定范围内。●确保所有团队成员都涉及引导干系人参与的活动（P503-504）　<span class="quiz-src">自编</span></p></details><p><a id="q9" class="quiz-anchor"></a></p><p><strong>9.</strong> 关于项目干系人的描述，正确的是（ ）。</p><ul><li>A．项目干系人是从项目中获利的个人、群体或组织</li><li>B．自认为受项目决策、活动或结果影响的个人、群体或组织也是干系人</li><li>C．干系人分析是在项目计划阶段实施的工作，在项目其它阶段不涉及</li><li>D．干系人之间的关系不是干系人分析的工作内容</li></ul><details class="quiz" data-q="9" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：O3。当前新技术快速发展，“干系人”一词的外延正在扩大，从传统意义上的员工、供应商和高层管理者扩展到涵盖各式群体，包括监管机构、环保人士、金融组织、媒体，以及那些自认为是干系人的人员（他们认为自己公受项目工作或成果的影响）（P5）　<span class="quiz-src">2019 年下半年高项</span></p></details><p><a id="q10" class="quiz-anchor"></a></p><p><strong>10.</strong> 关于项目干系人管理的发展趋势和新兴实践的描述，不正确的是（ ）。</p><ul><li>A．确保团队都涉及引导干系人参与的活动</li><li>B．关注干系人有效参与的正面与负面价值</li><li>C．视受项目影响最大的干系人为合作伙伴</li><li>D．在限定范围内识别项目的所有干系人</li></ul><details class="quiz" data-q="10" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：O3。项目干系人管理的发展趋势和新兴实践主要包括：●识别所有干系人，而非在限定范用内。●确保所有团队成员都涉及引导干系人参与的活动（P5）　<span class="quiz-src">2025 年高项第 2 批</span></p></details><p><a id="q11" class="quiz-anchor"></a></p><p><strong>11.</strong> 在项目干系人管理过程中，核心是“根据干系人的需求、期望、利益和潜在影响，制定其参与项目的方法”的过程是（ ）。</p><ul><li>A．识别干系人</li><li>B．规划干系人参与</li><li>C．管理干系人参与</li><li>D．监督干系人参与</li></ul><details class="quiz" data-q="11" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：规划干系人参与：根据干系人的需求、期望、利益和对项目的潜在影响，制定项目干系人参与项目的方法（P504）　<span class="quiz-src">自编</span></p></details><p><a id="q12" class="quiz-anchor"></a></p><p><strong>12.</strong> 项目执行过程中，需要与干系人沟通协作、处理其问题以促进合理参与，这属于以下哪个干系人管理过程（ ）。</p><ul><li>A．识别干系人</li><li>B．规划干系人参与</li><li>C．管理干系人参与</li><li>D．监督干系人参与</li></ul><details class="quiz" data-q="12" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：O4。管理干系人参与：与干系人进行沟通和协作，以满足其需求与期望，并处理问题，以促进干系人合理参与（P5）　<span class="quiz-src">自编</span></p></details><p><a id="q13" class="quiz-anchor"></a></p><p><strong>13.</strong> 关于项目干系人管理的描述，不正确的是（ ）。</p><ul><li>A．应把干系人满意度作为一个关健项目目标来进行管理</li><li>B．规划干系人参与是一个反复的过程，应由项目经理定期开展</li><li>C．项目干系人管理包含项目需求管理、沟通管理和人力资源管理</li><li>D．建立沟通管理计划是为管理干系人的期望提供指导和信息</li></ul><details class="quiz" data-q="13" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：项目干系人管理的过程包括：●识别干系人●规划干系人参与●管理干系人参与●监督王系人叁与（P504）　<span class="quiz-src">2022 年上半年高项</span></p></details><p><a id="q14" class="quiz-anchor"></a></p><p><strong>14.</strong> 在项目干系人管理过程中，项目经理可以根据不同的因素对干系人管理过程进行适当的裁剪需要考虑的因素不包括（ ）。</p><ul><li>A．干系人多样性</li><li>B．干系人关系的复杂性</li><li>C．开发方法</li><li>D．沟通技术</li></ul><details class="quiz" data-q="14" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：考虑因素：王系人多样性、王系人关系的复杂性、沟通技术（P505）　<span class="quiz-src">自编</span></p></details><p><a id="q15" class="quiz-anchor"></a></p><p><strong>15.</strong> 敏捷或适应型环境中的干系人管理不正确的是（ ）。</p><ul><li>A．频繁变化的项目更需要项目干系人的有效互动和参与。</li><li>B．适应型团队会直接与干系人互动。</li><li>C．客户、用户和开发人员在动态的共创过程中交换信息，干系人参与和满意程度更高</li><li>D．为加快组织内部和组织之间的信息分享，敏捷型方法提倡实时的视频沟通</li></ul><details class="quiz" data-q="15" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：O5。为加快组织内部和组织之间的信息分辛，敏捷型方法提倡高度透明。例如，邀请所有干系人参与项目会议和审查，或将项目工件发布到公共空间，其目的在于让各方之间的不一致和依赖关系，或者与项目有关的其他变化问题，都尽快浮现（P5）　<span class="quiz-src">自编</span></p></details><p><a id="q16" class="quiz-anchor"></a></p><p><strong>16.</strong> 识别干系人的依据不包括（ ）。</p><ul><li>A．可行性研究报告</li><li>B．项目章程</li><li>C．风险登记册</li><li>D．问题日志</li></ul><details class="quiz" data-q="16" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：识别干系人的依据就是识别干系人的输入。识别干系人的输入包括：1立项管理文件；2项目章程；3项目管理计划（沟通管理计划、干系人参与计划）;4.项目文件（需求文件、问题且志、变更日志）;5协议；6.事业环境因素；7组织过程资产（P506-507）　<span class="quiz-src">教材第 17 章章节习题</span></p></details><p><a id="q17" class="quiz-anchor"></a></p><p><strong>17.</strong> 关于项目识别干系人过程的描述，下列说法正确的是（ ）。</p><ul><li>A．仅在编制和批准项目章程之后首次开展，后续无需重复</li><li>B．核心作用是使项目团队对每个干系人或干系人群体建立适度关注</li><li>C．无需查阅项目管理计划组件，仅通过新增调研即可完成干系人识别</li><li>D．仅在项目生命周期阶段开始时重复开展，组织发生重大变化时无需调整</li></ul><details class="quiz" data-q="17" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：O5。识别干系人是定期识别项目干系人，分析和记录他们的利益、参与度、相互依赖性、影响力和对项目成功的潜在影响的过程。本过程的主要作用是，使项目团队能能建立对每个干系人或干系人群体的适度关注（P5）　<span class="quiz-src">自编</span></p></details><p><a id="q18" class="quiz-anchor"></a></p><p><strong>18.</strong> 识别干系人过程（ ）。</p><ul><li>A．需要在整个项目期间定期开展</li><li>B．本过程需要在整个项目期间开展</li><li>C．仅开展一次</li><li>D．仅在项目的预定义时开展</li></ul><details class="quiz" data-q="18" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：识别干系人：需要在整个项目期间定期开展（P505）　<span class="quiz-src">自编</span></p></details><p><a id="q19" class="quiz-anchor"></a></p><p><strong>19.</strong> 以下说法中不正确的是（ ）。</p><ul><li>A．为提高项目成功的概率尽早开始识别干系人并引导干系人参与</li><li>B．当项目管理计划制订后，就可以开始识别干系人工作了</li><li>C．识别干系人和引导干系人参与的过程需要选代开展</li><li>D．当组织内部或更大领域的干系人群体发生重大变化时，需要重新识别干系人</li></ul><details class="quiz" data-q="19" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：O6。在首次识别王系人时，项目管理计划并不存在。之后识别干系人时，可以参考项目管理计划里的沟通计划等因素（P5）　<span class="quiz-src">自编</span></p></details><p><a id="q20" class="quiz-anchor"></a></p><p><strong>20.</strong> 首次识别干系人时要以（ ）为依据。</p><ul><li>A．项目管理计划</li><li>B．沟通管理计划</li><li>C．干系人参与计划</li><li>D．项目章程</li></ul><details class="quiz" data-q="20" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：O6。首次识别干系人的输入并不包括所有项目文件，其中ABC这个时候是没有的，当识别完成后才有沟通计划，干系人参与计划。识别干系人的输入包括：1立项管理文件；2.项目章程；3.项目管理计划（沟通管理计划干系人参与计划）;4.项目文件（需求文件、问题日志、变更日志）;5协议；6半业环境因素7.组织过程资产、（P5）　<span class="quiz-src">自编</span></p></details><p><a id="q21" class="quiz-anchor"></a></p><p><strong>21.</strong> 头脑风暴是一种通用的数据收集和创意技术；（ ）是头脑风暴的改良形式</p><ul><li>A．思维导图</li><li>B．亲和图</li><li>C．焦点小组</li><li>D．头脑与作</li></ul><details class="quiz" data-q="21" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：O7。头脑风暴：用于识别干系人的头脑风暴技术包括头脑风暴和头脑写作。头脑风暴是一种通用的数据收集和创意技术；头脑写作是头脑风暴的改良形式（P5）　<span class="quiz-src">自编</span></p></details><p><a id="q22" class="quiz-anchor"></a></p><p><strong>22.</strong> 在识别干系人的时候，（ ）会产生干系人清单和关于干系人的各种信息。</p><ul><li>A．干系人分析</li><li>B．文件分析「</li><li>C．权力利益方格</li><li>D．干系人立方体</li></ul><details class="quiz" data-q="22" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：王系人分析：会产生干系人清单和关于干系人的各种信息（P507）　<span class="quiz-src">自编</span></p></details><p><a id="q23" class="quiz-anchor"></a></p><p><strong>23.</strong> 以下不属于干系人映射分析和表现技术的是（ ）。</p><ul><li>A．权力/利益方格</li><li>B．干系人立方体</li><li>C．干系人登记册</li><li>D．优先级排序</li></ul><details class="quiz" data-q="23" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：O8。适用于识别干系人过程的数据表现技术是干系人映射分析和表现。干系人映射分析和表现是一种利用不同方法对干系人进行分类的方法（P5）　<span class="quiz-src">自编</span></p></details><p><a id="q24" class="quiz-anchor"></a></p><p><strong>24.</strong> 复杂的干系人大型群体，适用（ ）来分析。</p><ul><li>A．权力利益方格</li><li>B．干系人立方体</li><li>C．凸显模型</li><li>D．影响方向</li></ul><details class="quiz" data-q="24" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：O8。凸显模型：通过评估干系人的权力、紧追性和合法性（参与的活当性），对干系人进行分类。在凸显模型中，也可以用邻近性取代合法性（P5）　<span class="quiz-src">自编</span></p></details><p><a id="q25" class="quiz-anchor"></a></p><p><strong>25.</strong> 临时贡献知识或技能的团队或专家，属于影响方向中（ ）类的干系人。</p><ul><li>A．向上</li><li>B．向下</li><li>C．向外</li><li>D．横向</li></ul><details class="quiz" data-q="25" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：O8。影响方向：可以根据干系人对项目工作或项目团队本身的影响方向，对干系人进行分类可以把干系人分类为：①向上。执行组织或客户组织、发起人和指导委员会的高级管理层②向下（P5）　<span class="quiz-src">自编</span></p></details><p><a id="q26" class="quiz-anchor"></a></p><p><strong>26.</strong> 项目经理的同级人员，属于影响方向中（ ）类的干系人。</p><ul><li>A．向上</li><li>B．向下</li><li>C．向外</li><li>D．横向</li></ul><details class="quiz" data-q="26" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：O8。影响方向：可以根据干系人对项目工作或项目团队本身的影响方向，对干系人进行分类可以把干系人分类为：①向上。执行组织或客户组织、发起人和指导委员会的高级管理层②向下（P5）　<span class="quiz-src">自编</span></p></details><p><a id="q27" class="quiz-anchor"></a></p><p><strong>27.</strong> 在干系人分类方法中，干系人改变项目计划或执行的能力，属于干系人的（ ）</p><ul><li>A．权力</li><li>B．利益</li><li>C．影响</li><li>D．作用</li></ul><details class="quiz" data-q="27" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：O8。权力利益方格、权力影响方格或作用影响方格：基于干系人的职权级别（权力）、对项目成果的关心程度（利益）、对项目成果的影响能力（影响），或改变项目计划或热行的能力（作用）（P5）　<span class="quiz-src">自编</span></p></details><p><a id="q28" class="quiz-anchor"></a></p><p><strong>28.</strong> 关于识别干系人过程的工具和技术及相关应用，正确的是（ ）。</p><ul><li>A．权力利益方格属于数据收集技术，适用于复杂的干系人大型群体</li><li>B．凸显模型通过评估干系人的权力、紧迫性和合法性，对干系人分类，可确定干系人相对重要性</li><li>C．干系人立方体是二维模型，基于干系人的权力和利益对其进行分类</li><li>D．影响方向分类中，供应商、政府机构属于“向下”影响的干系人</li></ul><details class="quiz" data-q="28" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：O8。A不正确。权力利益方格属于数据表现技术，而非数据收集技术，且适用于干系人关系简单的项目，复杂大型群体更适合凸显模型（P5）　<span class="quiz-src">自编</span></p></details><p><a id="q29" class="quiz-anchor"></a></p><p><strong>29.</strong> 某公司启动一个大型复杂项目，涉及多方主体，干系人群体庞大且关系复杂。项目经理在首次识别干系人后，需进一步细化干系人分类，以便制定针对性的沟通策略。此时，最适合采用的干系人分类方法是（ ）。</p><ul><li>A．权力利益方格，适用于复杂干系人群体的分类</li><li>B．凸显模型，通过评估权力、紧迫性和合法性对干系人分类</li><li>C．影响方向分类，将干系人分为向上、向下、横向三类</li><li>D．干系人立方体，仅适用于干系人关系简单的项目</li></ul><details class="quiz" data-q="29" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：O8。选项A:权力利益方格适用于干系人关系简单的项目，本题项目复杂、干系人群体庞大，不适用。选项B:凸显模型通过评估干系人的权力、紧迫性和合法性（或部近性）对干系人进行分类，适用于复杂的干系人大型群体，且可确定干系人相对重要性，便于制定针对性沟通策略，最为合适（P5）　<span class="quiz-src">自编</span></p></details><p><a id="q30" class="quiz-anchor"></a></p><p><strong>30.</strong> 识别干系人过程通常在编制和批准（ ）之前或同时首次开展，其数据表现包括（ ）;输出包括干系人登记册和（ ）。</p><ul><li>A．项目章程、干系人立方体、假设日志</li><li>B．项目计划、干系人立方体、变更请求</li><li>C．项目章程、干系人分析、假设日志</li><li>D．项目计划、干系人分析、变更请求</li></ul><details class="quiz" data-q="30" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：P505。识别王系人管理过程通常在编制和批准项目章程之前或同时首次开展，之后在项目生命周期过程中必要时重复开展，至少应在每个阶段开始时，以及项目或组织出现重大变化时重复开展（P505-509）　<span class="quiz-src">自编</span></p></details><p><a id="q31" class="quiz-anchor"></a></p><p><strong>31.</strong> （ ）不属于干系人登记册的内容。</p><ul><li>A．身份信息</li><li>B．评估信息</li><li>C．隐私信息</li><li>D．干系人分类</li></ul><details class="quiz" data-q="31" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：干系人登记册是识别干系人过程的主要输出，记录已识别干系人的信息，主要包括：●身份信息：姓名、组织职位、地点、联系方式，以及在项目中扮演的角色●评估信息：主要需求、期望、影响项目成果的潜力，以及干系人最能影响或冲击的项目生命周期阶段（P508-509）　<span class="quiz-src">自编</span></p></details><p><a id="q32" class="quiz-anchor"></a></p><p><strong>32.</strong> 首次识别干系人的输出有（ ）。</p><ul><li>A．变更请求</li><li>B．项目管理计则更新</li><li>C．干系人登记册</li><li>D．沟通管理计划更新</li></ul><details class="quiz" data-q="32" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：首次识别干系人的时候，还没有项目管理计划等其他文件，自然不需要提出变更请求，也不需要更新其他项目文性（P508-509）　<span class="quiz-src">自编</span></p></details><p><a id="q33" class="quiz-anchor"></a></p><p><strong>33.</strong> 以下属于“识别干系人”过程的数据分析技术的是（ ）。</p><ul><li>A．干系人立方体</li><li>B．多标准决策分析</li><li>C．干系人分析</li><li>D．回归分析</li></ul><details class="quiz" data-q="33" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：，适用于识别王系人过程的数损分析技术主要包括王系人分析和文住分析等（P507-508）　<span class="quiz-src">2025 年中项第 1 批</span></p></details><p><a id="q34" class="quiz-anchor"></a></p><p><strong>34.</strong> 城市建设工地被附近小区居民投诉，以下采取哪个措施是对的（ ）。</p><ul><li>A．客户投诉噪音，纳入干系人登记册</li><li>B．媒体曝光，影响舆论</li><li>C．将记者和干系人归类为中立型</li><li>D．张贴施工通告、发布安民告示</li></ul><details class="quiz" data-q="34" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：课本无原话。综合项目管理知识，最正确、最基础、最符合流程的答案是A。它体现了“识别所有王系人”这一干系人管理新实践和首要步骤，是后续一切沟通、管理、监督活动的基础　<span class="quiz-src">2025 年中项第 1 批</span></p></details><p><a id="q35" class="quiz-anchor"></a></p><p><strong>35.</strong> （ ）可以提供关于潜在干系人的信息。</p><ul><li>A．干系人参与计划</li><li>B．经验教训登记册</li><li>C．需求文件</li><li>D．沟通管理计划</li></ul><details class="quiz" data-q="35" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：需求文件。需求文件可以提供关于潜在干系人的信息（P507）　<span class="quiz-src">2025 年中项第 2 批</span></p></details><p><a id="q36" class="quiz-anchor"></a></p><p><strong>36.</strong> 在完成规划干系人参与过程后，将市大数据局信息中心主任的联系方式在（ ）中进行了补充修正。</p><ul><li>A．干系人登记册</li><li>B．干系人参与计划</li><li>C．沟通管理计划</li><li>D．绩效评估</li></ul><details class="quiz" data-q="36" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：508-509。干系人登记册记录关于已识别干系人的信息，主要包括身份信息、评估信息和干系人分类等。“(1)身份信息。身份信息包括姓名、组织职位、地点、联系方式，以及在项目中扮演的角色　<span class="quiz-src">2025 年中项第 2 批</span></p></details><p><a id="q37" class="quiz-anchor"></a></p><p><strong>37.</strong> 在了解和管理干系人期望时，可以采用多种分类方法对干系人进行分类管理。其中（ ）方法是根据干系人主动参与项目的程度改变项目计划或执行的能力进行分组。</p><ul><li>A．权力/利益方格</li><li>B．权力/影响方格</li><li>C．影响/作用方格</li><li>D．凸显模型</li></ul><details class="quiz" data-q="37" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：对项目成果的影响能力（影响），改变项目计划或执行的能力（作用）（P508）　<span class="quiz-src">2018 年上半年高项</span></p></details><p><a id="q38" class="quiz-anchor"></a></p><p><strong>38.</strong> 某大型环保信息系统工程建设项目，项目发起人与项目经理一起识别出如下3类项目干系人：甲方信息系统管理人员、项目组主要技术人员、监理方，并准备针对他们编制干系人管理计划对此，您的建议是（ ）。</p><ul><li>A．重新识别干系人</li><li>B．编制干系人管理计划</li><li>C．召开干系人管理沟通会议</li><li>D．编制项目进度计划</li></ul><details class="quiz" data-q="38" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：正确项为「重新识别干系人」，原解析未给课本依据　<span class="quiz-src">2019 年上半年高项</span></p></details><p><a id="q39" class="quiz-anchor"></a></p><p><strong>39.</strong> 某手机应用上线后，收到老年用户的多起投诉：界面繁琐，字体太小，使用不方便。这反映了项目组在（ ）工作中存在不足。</p><ul><li>A．变更控制</li><li>B．识别干系人</li><li>C．质量控制</li><li>D．团队建设</li></ul><details class="quiz" data-q="39" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：正确项为「识别干系人」，原解析未给课本依据　<span class="quiz-src">2020 年下半年高项</span></p></details><p><a id="q40" class="quiz-anchor"></a></p><p><strong>40.</strong> 根据干系人的权力、紧迫度和合法性对干系人进行分类的是（ ）</p><ul><li>A．凸显模型</li><li>B．影响/作用方格</li><li>C．权力/利益方格</li><li>D．权力/影响方格</li></ul><details class="quiz" data-q="40" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：O8。凸显模型：通过评估干系人的权力、紧迫性和合法性（参与的适当性），对干系人进行分类在凸显模型中，也可以用邻近性取代合法性（P5）　<span class="quiz-src">2021 年上半年高项</span></p></details><p><a id="q41" class="quiz-anchor"></a></p><p><strong>41.</strong> （ ）不属于识别干系人的输入。</p><ul><li>A．立项管理文件</li><li>B．变更日志和问题日志</li><li>C．沟通管理计划</li><li>D．项目干系人登记册</li></ul><details class="quiz" data-q="41" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：项目干系人登记册是识别干系人的输出，不是输入。识别干系人的输入包括：1.立项管理文件；2.项目章程；3.项目管理计划（沟通管理计划、干系人参与计划）;4.项目文件（需求文件、问题日志、变更日志）;5.协议；6.事业环境因素；7.组织过程资产（P506-507）　<span class="quiz-src">2023 年上半年高项</span></p></details><p><a id="q42" class="quiz-anchor"></a></p><p><strong>42.</strong> （ ）是通过干系人的权力、紧迫性、合法性对干系人进行分类</p><ul><li>A．凸显模型</li><li>B．权力利益方格</li><li>C．干系人立方体</li><li>D．影响方向</li></ul><details class="quiz" data-q="42" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：508。凸显模型是通过干系人的权力、紧迫性、合法性对王系人进行分类　<span class="quiz-src">2023 年下半年高项第 1 批</span></p></details><p><a id="q43" class="quiz-anchor"></a></p><p><strong>43.</strong> 以下（ ）不是干系人登记册的内容。</p><ul><li>A．身份信息</li><li>B．评估信息</li><li>C．干系人分类</li><li>D．干系人参与计划</li></ul><details class="quiz" data-q="43" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：干系人登记册是识别干系人过程的主要输出，记录已识别干系人的信息，主要包括：●身份信息：姓名、组织职位、地点、联系方式，以及在项目中扮演的角色●评估信息：主要需求、期望、影响项目成果的潜力，以及干系人最能影响或冲击的项目生命周期阶段（P508-509）　<span class="quiz-src">2023 年下半年高项第 2 批</span></p></details><p><a id="q44" class="quiz-anchor"></a></p><p><strong>44.</strong> （ ）是方格模型的改良形式。把方格中的要素组合成三维模型，作为一个多维模型，它将干系人视为一个多维实体，便于分析，从而有助于沟通策略的制定。</p><ul><li>A．权力/利益方格</li><li>B．干系人立方体</li><li>C．凸显模型</li><li>D．影响/作用方格</li></ul><details class="quiz" data-q="44" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：O8。王系人立方体；权力利益方格模型的改良形式。立方体把上述方格中的要素组合成三维模型，项目经理和团队可据此分析王系人并引导王系人参与项目（P5）　<span class="quiz-src">2023 年下半年高项第 3 批</span></p></details><p><a id="q45" class="quiz-anchor"></a></p><p><strong>45.</strong> 识别项目干系人管理过程在（ ）可以重复开展。①每个阶段开始时；②项目出现重大变化时；③进行可行性研究时；④组织出现重大变化时&quot;5编制项目章程时</p><ul><li>A．③④⑤</li><li>B．①2③</li><li>C．②③④</li><li>D．①②④</li></ul><details class="quiz" data-q="45" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：O5。识别干系人管理过程通常在编制和批准项目章程之前或同时首次开展，之后在项目生命周期过程中必要时重复开展，至少应在每个阶段开始时，以及项目或组织出现重大变化时重复开展每次重复开展识别干系人管理过程，都应通过查阅项目管理计划组件及项目文件，来识别有关的项目干系人（P5）　<span class="quiz-src">2023 年下半年高项第 4 批</span></p></details><p><a id="q46" class="quiz-anchor"></a></p><p><strong>46.</strong> 关于项目干系人管理的描述，正确的是（ ）。</p><ul><li>A．识别干系人过程的输出文件包括干系人登记册、工作绩效信息、变更请求</li><li>B．监管机构、环保人士、媒体与项目关联程度低，不需要纳入干系人管理</li><li>C．识别干系人过程需要在整个项目期间定期开展</li><li>D．干系人参与计划是规划干系人参与过程的输入文件</li></ul><details class="quiz" data-q="46" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：O5。A不正确，识别干系人过程的输出文件没有工作绩效信息。B不正确，只要是和项目相关的人都需要纳入干系人管理。C正确。识别干系人过程需要在整个项目期间定期开展D不正确，干系人参与计划是规划干系人参与过程的输出文件（P5）　<span class="quiz-src">2024 年高项第 1 批</span></p></details><p><a id="q47" class="quiz-anchor"></a></p><p><strong>47.</strong> 关于识别干系人过程的描述，不正确的是（ ）。</p><ul><li>A．干系人登记册是识别干系人过程的主要输出记录已识别干系人的信息</li><li>B．变更日志、问题日志、需求文件可以作为识别干系人过程的输入</li><li>C．对干系人进行分类的方法，包括权力利益方格、因果图、回归分析、凸显模型等</li><li>D．识别干系人的主要作用是使项目团队能够建立对每个干系人或干系人群体的适度关注</li></ul><details class="quiz" data-q="47" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：因果图，回归分析均不属于干系人分类方法干系人分类方法包括：1权力利益方格、权力影响方格，或作用影响方格；2.干系人立方体3.凸显模型；4.影响方向；5.优先级排序（P508）　<span class="quiz-src">2024 年高项第 1 批</span></p></details><p><a id="q48" class="quiz-anchor"></a></p><p><strong>48.</strong> （ ）适用于复杂的干系人大型群体，或在干系人群体内部存在复杂的关系网络，可用于确定已识别干系人的相对重要性。</p><ul><li>A．优先级排序</li><li>B．影响方间</li><li>C．权力利益方格</li><li>D．凸显模型</li></ul><details class="quiz" data-q="48" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：O8。凸显模型适用于复杂的干系人大型群体，或在干系人群体内部存在复杂的关系网络。凸显模型可用于确定已识别干系人的相对重要性（P5）　<span class="quiz-src">2025 年高项第 2 批</span></p></details><p><a id="q49" class="quiz-anchor"></a></p><p><strong>49.</strong> 可作为识别干系人过程输入的项目文件不包括（ ）。</p><ul><li>A．问题日志</li><li>B．变更日志</li><li>C．需求文件</li><li>D．干系人登记册</li></ul><details class="quiz" data-q="49" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：首次识别干系人的输入并不包括所有项目文件，要在整个项目期间定期识别干系人。项目经历启动阶段以后，将会生成更多项目文件，用于后续的项目阶段（P506-507）　<span class="quiz-src">2026 年高项第 1 批</span></p></details><p><a id="q50" class="quiz-anchor"></a></p><p><strong>50.</strong> 关于项目干系人管理的描述，不正确的是（ ）。</p><ul><li>A．项目进入不同生命周期时应开展项目干系人识别与排序</li><li>B．项目经理和团队的管理干系人的能力决定着项目的成败</li><li>C．项目干系人公对项目产生积极或消极的影响</li><li>D．首次识别干系人需要在项目章程批准之后尽快开展</li></ul><details class="quiz" data-q="50" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：O5。识别干系人管理过程通常在编制和批准项目章程之前或同时首次开展，之后在项目生命周期过程中必要时重复开展（P5）　<span class="quiz-src">2026 年高项第 2 批</span></p></details><p><a id="q51" class="quiz-anchor"></a></p><p><strong>51.</strong> （ ）适用于在干系人群体内存在复杂网络关系时使用；（ ）适用于小型项目、干系人与项目的关系简单且稳定的项目。</p><ul><li>A．权力影响方格、凸显模型</li><li>B．权力利益方格、优先级排序</li><li>C．干系人立方体、凸显模型</li><li>D．凸显模型、权力影响方格</li></ul><details class="quiz" data-q="51" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：O8。凸显模型适用于复杂的干系人大型群体，或在干系人群体内部存在复杂的关系网络。凸显模型可用于确定已识别干系人的相对重要性（P5）　<span class="quiz-src">2026 年高项第 2 批</span></p></details><p><a id="q52" class="quiz-anchor"></a></p><p><strong>52.</strong> 规划干系人参与是根据干系人的需求、期望、利益和对项目的潜在影响，制定项目干系人参与项目的方法的过程，其主要作用是（ ）。</p><ul><li>A．在整个项目期间为如何管理项目成本提供指南和方向</li><li>B．确定项目所需的资金</li><li>C．提供与干系人进行有效互动的可行计划</li><li>D．为及时向干系人提供相关信息、引导干系人有效参与项目而编制书面沟通计划</li></ul><details class="quiz" data-q="52" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：O9。规划干系人参与是根据干系人的需求、期望、利益和对项目的潜在影响，制定项目干系人参与项目的方法的过程。本过程的主要作用是，提供与干系人进行有效互动的可行计划（P5）　<span class="quiz-src">自编</span></p></details><p><a id="q53" class="quiz-anchor"></a></p><p><strong>53.</strong> 应该在什么时候编制第一版的干系人参与计划（ ）。</p><ul><li>A．明确最初的干系人群体之后</li><li>B．制订项目章程</li><li>C．制定项目管理计划</li><li>D．识别干系人</li></ul><details class="quiz" data-q="53" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：O9。在通过识别干系人过程明确最初的干系人群体之后，就应该编制第一版的干系人参与计划，然后定期更新干系人参与计划，以反映干系人群体的变化（P5）　<span class="quiz-src">自编</span></p></details><p><a id="q54" class="quiz-anchor"></a></p><p><strong>54.</strong> 关于“规划干系人参与”过程的描述，不正确的是（ ）。</p><ul><li>A．风险管理计划可能包含风险临界值或风险态度，有助于选择最佳的干系人参与策略组合</li><li>B．规划干系人参与的主要作用是提供干系人进行有效互动的可行计划</li><li>C．干系人参与度评估矩阵用于将干系人当前参与水平与期望参与水平进行比较</li><li>D．为避免干系人变化的影响，不应在项目早期编制干系人参与计划</li></ul><details class="quiz" data-q="54" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：509。为满足项目干系人的多样性信息需求，应在项目生命周期的早期制江一份有效的计划　<span class="quiz-src">自编</span></p></details><p><a id="q55" class="quiz-anchor"></a></p><p><strong>55.</strong> 关于规划干系人参与过程的相关描述，正确的是（ ）。“①规划干系人参与是根据干系人需求、期望等，制定其参与项目方法的过程②规划干系人参与过程仅开展一次或仅在项目的预定义点开展，此后更新计划即可③识别干系人过程明确最初干系人群体后，应编制第一版干系人参与计划④干系人参与度评估矩阵用于将干系人期望参与水平与历史参与水平对比⑤原先分管项目的副总刘总不再担任本项目的任何职位，不需要更新干系人参与计划</p><ul><li>A．①②③</li><li>B．①3</li><li>C．②④5</li><li>D．④⑤</li></ul><details class="quiz" data-q="55" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：O9。规划干系人参与的定义为：根据王系人的需求、期望、利益和对项目的潜在影响，制定项目干系人参与项目的方法的过程，①描述正确，规划干系人参与需要在整个项目期间定期开展，且需定期更新干系人参与计划，并非仅开展一次，②描述错误（P5）　<span class="quiz-src">自编</span></p></details><p><a id="q56" class="quiz-anchor"></a></p><p><strong>56.</strong> 会触发干系人参与计划更新的情况不包括（ ）。</p><ul><li>A．项目新阶段开始</li><li>B．组织结构或行业内部发生变化</li><li>C．项目管理计划的更新</li><li>D．新的个人或群体成为干系人，现有干系人不再是干系人群体的成员，或特定干系人对项目成功的重要性发生变化</li></ul><details class="quiz" data-q="56" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：会触发干系人参与计划更新的情况主要包括：①项目新阶段开始；②组织结构或行业内部发生变化；Q新的个人或群体成为王系人，现有干系人不再是干系人群体的成员，或特定干系人对项目成功的重要性发生变化；④当其他项目过程（如变更管理、风险管理或问题管理）的输出导致需要重新审查干系人参与策略等（P509-510）　<span class="quiz-src">自编</span></p></details><p><a id="q57" class="quiz-anchor"></a></p><p><strong>57.</strong> 下面哪种情况可以不用更新干系人参与计划（ ）。</p><ul><li>A．项目成员小张晋升为小组长</li><li>B．项目需求阶段完毕，开始进入开发阶段</li><li>C．甲方项目经理高升</li><li>D．公司的组织战略发生了调整，新增了SAAS平台运营部</li></ul><details class="quiz" data-q="57" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：正确项为「公司的组织战略发生了调整，新增了SAAS平台运营部」，原解析未给课本依据　<span class="quiz-src">自编</span></p></details><p><a id="q58" class="quiz-anchor"></a></p><p><strong>58.</strong> 关于管理干系人参与过程的描述，正确的是（ ）。</p><ul><li>A．仅项目章程可作为管理干系人参与的输入，项目管理计划无参考价值</li><li>B．沟通管理计划作为项目管理计划组件，可作为该过程输入并提供沟通策略支持</li><li>C．风险登记册无法为管理干系人参与提供有效依据</li><li>D．干系人登记册未包含干系人分类信息，不能支撑参与管理活动开展</li></ul><details class="quiz" data-q="58" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：O。沟通管理计划：用于干系人管理的沟通策略以及用于实施策略的计划，既是项目干系人管理中的各个过程的输入，又公收录来自这些过程的相关信息（P51）　<span class="quiz-src">自编</span></p></details><p><a id="q59" class="quiz-anchor"></a></p><p><strong>59.</strong> （ ）识别是什么根本原因导致了干系人对项目的某种支持水平。</p><ul><li>A．标杆对照</li><li>B．假设条件和制约因素分析</li><li>C．根本原因分析</li><li>D．干系人参与度评估矩阵</li></ul><details class="quiz" data-q="59" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：报本原因分析：识别是什么根本原因导致了王系人对项目的基种支持水平（P511）　<span class="quiz-src">自编</span></p></details><p><a id="q60" class="quiz-anchor"></a></p><p><strong>60.</strong> （ ）将干系人分析的结果与其他被视为具备引领级的组织或项目的信息进行比较</p><ul><li>A．标杆对照</li><li>B．根本原因分析</li><li>C．思维导</li><li>D．干系人参与度评估矩阵</li></ul><details class="quiz" data-q="60" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：标杆对照：将干系人分析的结果与其他被视为具备引领级的组织或项目的信息进行比较（P511）　<span class="quiz-src">自编</span></p></details><p><a id="q61" class="quiz-anchor"></a></p><p><strong>61.</strong> 关于干系人参与度评估矩阵，以下说法，错误的是（ ）</p><ul><li>A．矩阵中用字母C表示每个干系人的当前参与水平</li><li>B．矩阵中用字母D表示是项目团队评估出来的参与水平</li><li>C．中立型了解项目，会支持项目工作及其成果</li><li>D．领导型了解项目及其潜在影响，而且积极参与以确保项目取得成功</li></ul><details class="quiz" data-q="61" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：干系人参与度评估矩阵：用于将干系人当前参与水平与期望参与水平进行比较，干系人参与水平可分为如下：①不了解型：不知道项目及其潜在影响（P512）　<span class="quiz-src">自编</span></p></details><p><a id="q62" class="quiz-anchor"></a></p><p><strong>62.</strong> （ ）对干系人信息、相互关系以及他们与组织的关系进行可视化整理</p><ul><li>A．标杆对照</li><li>B．思维导图</li><li>C．根本原因分析</li><li>D．干系人参与度评估矩阵</li></ul><details class="quiz" data-q="62" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：思维导图：对干系人信息、相互关系以及他们与组织的关系进行可视化整理（P512）　<span class="quiz-src">自编</span></p></details><p><a id="q63" class="quiz-anchor"></a></p><p><strong>63.</strong> （ ）用于将干系人当前参与水平与期望参与水平进行比较，对干系人参与水平进行分类</p><ul><li>A．思维导图</li><li>B．干系人参与度评估矩阵</li><li>C．干系人参与计划</li><li>D．根本原因分析</li></ul><details class="quiz" data-q="63" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：王系人参与度评估矩阵：用于将干系人当前参与水平与期望参与水平进行比较。对干系人参与水平进行分类的方式之二（P512）　<span class="quiz-src">自编</span></p></details><p><a id="q64" class="quiz-anchor"></a></p><p><strong>64.</strong> 以下说法中不正确的是（ ）。</p><ul><li>A．干系人参与计划可以是正式的或非正式的，非常详细的或高度概括的</li><li>B．在通过识别干系人过程明确最初的干系人群体之后，就应该编制第一版的干系人参与计划，然后定期更新干系人参与计划</li><li>C．团队评估项目干系人A对项目的参与程度是不抵制，现在A非常积极的支持项目，这种是好情况，代表项目深受干系人欢迎，所以不用采取引导措施</li><li>D．当特定干系人对项目成功的重要性发生变化时，需要重新规划干系人参与</li></ul><details class="quiz" data-q="64" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：C不正确。项目干系人不是越支持项目就对项目越有利，有时候会因为过多参与项目，导致项目受负面影响（P512）　<span class="quiz-src">自编</span></p></details><p><a id="q65" class="quiz-anchor"></a></p><p><strong>65.</strong> 在对干系人参与水平分类时可以分为（ ）。①不了解型；②抵制型；③中立型；④支持型；⑤参与型</p><ul><li>A．①②④</li><li>B．①③⑤</li><li>C．②③④</li><li>D．①②③④</li></ul><details class="quiz" data-q="65" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：干系人参与度评估矩阵：用于将干系人当前参与水平与期望参与水平进行比较，干系人参与水平可分为如下：①不了解型：不知道项目及其潜在影响（P512）　<span class="quiz-src">自编</span></p></details><p><a id="q66" class="quiz-anchor"></a></p><p><strong>66.</strong> 关于“规划干系人参与”过程的描述，不正确的是（ ）。</p><ul><li>A．干系人参与计划制定干系人有效参与和执行项目决策的策略和行动</li><li>B．规划干系人参与的主要作用是提供干系人进行有效互动的可行计划</li><li>C．干系人参与度评估矩阵用于将干系人当前参与水平与期望参与水平进行比较</li><li>D．为避免干系人变化的影响，不应在项目早期编制干系人参与计划</li></ul><details class="quiz" data-q="66" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：为满足项目干系人的多样性信息需求，应在项目生命周期的早期制江一份有效的计划（P509）　<span class="quiz-src">2024 年中项第 1 批</span></p></details><p><a id="q67" class="quiz-anchor"></a></p><p><strong>67.</strong> 干系人参与度评估矩阵适用于（ ）。①规划干系人参与；②管理干系人参与；③监督干系人参与；④管理团队；⑤管理沟通；⑥监督沟通</p><ul><li>A．③⑤⑥</li><li>B．①②④</li><li>C．②④6</li><li>D．①③⑥</li></ul><details class="quiz" data-q="67" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：干系人参与度评估矩阵适用于规划干系人参与；监督王系人参与；规划沟通管理；监督沟通（P422）　<span class="quiz-src">2024 年中项第 2 批</span></p></details><p><a id="q68" class="quiz-anchor"></a></p><p><strong>68.</strong> 根据干系人的参与水平分类，（ ）干系人会积极参与到项目中。①不了解型；②抵制型；③中立型；④支持型；⑤领导型</p><ul><li>A．5</li><li>B．④⑤</li><li>C．③④⑤</li><li>D．②③④⑤</li></ul><details class="quiz" data-q="68" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：干系人参与度评估矩阵：用于将干系人当前参与水平与期望参与水平进行比较，干系人参与水平可分为如下：①不了解型：不知道项目及其潜在影响（P512）　<span class="quiz-src">2024 年中项第 2 批</span></p></details><p><a id="q69" class="quiz-anchor"></a></p><p><strong>69.</strong> （ ）干系人了解项目及其潜在影响，而且积极参与以确保项目取得成功。</p><ul><li>A．协调型</li><li>B．支持型</li><li>C．领导型</li><li>D．中立型</li></ul><details class="quiz" data-q="69" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：干系人参与度评估矩阵：用于将干系人当前参与水平与期望参与水平进行比较。干系人参与水平可分为如下：●不了解型：不知道项目及其潜在影响（P512）　<span class="quiz-src">2025 年中项第 1 批</span></p></details><p><a id="q70" class="quiz-anchor"></a></p><p><strong>70.</strong> （ ）干系人积极参与，以确保项目取得成功，（ ）干系人知道项目及其潜在影响，但抵制项目工作或成果可能引发的任何变更。</p><ul><li>A．支持型、抵制型</li><li>B．抵制型、支持型</li><li>C．抵制型、领导型</li><li>D．领导型、抵制型</li></ul><details class="quiz" data-q="70" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：干系人参与水平可分为如下几种：●不了解型：不知道项目及其潜在影响；●抵制型：知道项目及其潜在影响，但抵制项目工作或成果可能引发的任何变更，此类干系人不会支持项目工作或项目成果；●中立型：了解项目，但既不支持，也不反对；●支持型：了解项目及其潜在影响，并且会支持项目工作及其成果；●领导型：了解项目及其潜在影响，而且积极参与，以确保项目取得成功（P512）　<span class="quiz-src">2025 年中项第 4 批</span></p></details><p><a id="q71" class="quiz-anchor"></a></p><p><strong>71.</strong> 干系人参与计划制定后需要更新，可能触发该计划更新的情况不包括（ ）。</p><ul><li>A．风险管理过程中识别到新的合规问题需引入新的干系人</li><li>B．管理质量过程中干系人对项目状态不满要求复盘</li><li>C．企业组织结构调整引发的项目成员离开团队</li><li>D．项目新阶段开始</li></ul><details class="quiz" data-q="71" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：509-510。公触发干系人参与计划更新的情况主要包括：&quot;项目新阶段开始：·组织结构或行业内部发生变化；·新的个人或群体成为干系人，现有干系人不再是干系人群体的成员，或特定干系人对项目成功的重要性发生变化：当其他项目过程（如变更管理、风险管理或问题管理）的输出导致需要重新审查干系人参与策略等　<span class="quiz-src">2026 年上半年中项第 1 批</span></p></details><p><a id="q72" class="quiz-anchor"></a></p><p><strong>72.</strong> 干系人参与度评估矩阵内一个干系人的当前参与水平是抵制，以下正确的选项是（ ）</p><ul><li>A．无需理会</li><li>B．换一个干系人</li><li>C．将表格中的抵制改成支持</li><li>D．通过积极倾听或引导等方式获取干系人的支持</li></ul><details class="quiz" data-q="72" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：512。应根据每个干系人的当前与期望参与水平的差距，开展必要的沟通，有效引导干系人参与项目。张合当前与期望参与水平的差距是监督干系人参与的一项基本工作　<span class="quiz-src">2026 年上半年中项第 2 批</span></p></details><p><a id="q73" class="quiz-anchor"></a></p><p><strong>73.</strong> 关于项目干系人管理的描述，不正确的是（ ）。</p><ul><li>A．项目成员的家属也可能成为项目干系人</li><li>B．整个项目周期中项目干系人都可能发生增减变化</li><li>C．规划干系人参与应由项目经理在项目规划阶段完成</li><li>D．应把干系人满意度作为一个关键的项目目标来管理</li></ul><details class="quiz" data-q="73" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：规划干系人参与是一个反复过程，应由项目经理定期开展（P509）　<span class="quiz-src">2021 年上半年高项</span></p></details><p><a id="q74" class="quiz-anchor"></a></p><p><strong>74.</strong> 在以下干系人参与度矩阵中，需要授权管理职责并引导其积极参与项目执行的干系人是（ ）中立 支持 领导干系人 不知晓 抵制干系人1Oi O干系人2王素人3意 O注：〇表示期望参与水平，●表示实际参与水平</p><ul><li>A．干系人1</li><li>B．干系人3</li><li>C．干系人2</li><li>D．干系人2和干系人3</li></ul><details class="quiz" data-q="74" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：这题属于文字游戏，从题意来看，希望他领导，当然需要授权管理职责，所以干系人3正确干系人2为什么不正确，因为干系人2只需要他支持，可以不用授权管理职责，太家一定要看洁楚是“管理&quot;职责（P512）　<span class="quiz-src">2023 年上半年高项</span></p></details><p><a id="q75" class="quiz-anchor"></a></p><p><strong>75.</strong> 以下（ ）不是规划干系人参与的输入。</p><ul><li>A．资源管理计划</li><li>B．风险管理计划</li><li>C．干系人登记册</li><li>D．干系人参与计划</li></ul><details class="quiz" data-q="75" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：干系人参与计划是输出。规划干系人参与的输入就是规划干系人参与的输入。规划干系人参与的输入：1项目章程；2.项目管理计划（资源管理计划、沟通管理计划、风险管理计划）;3.项目文件（假设日志、风险登记册、干系人登记册、项目进度计划、问题日志、变更日志）;4.协议；5.事业环境因素；6.组织过程资产（P510-511）　<span class="quiz-src">2023 年下半年高项第 2 批</span></p></details><p><a id="q76" class="quiz-anchor"></a></p><p><strong>76.</strong> 关于干系人参与度评估矩阵，以下说法，错误的是（ ）。</p><ul><li>A．干系人参与度评估矩阵：用于将干系人当前参与水平与期望参与水平进行比较</li><li>B．C是项目团队评估出来的、为确保项目成功所必不可少的参与水平（期望的）</li><li>C．支持型是指了解项目及其潜在影响，并且会支持项目工作及其成果</li><li>D．应根据每个干系人的当前与期望参与水平的差距，开展必要的沟通，有效引导干系人参与项目</li></ul><details class="quiz" data-q="76" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：干系人参与度评估矩阵：用于将干系人当前参与水平与期望参与水平进行比较。对干系人参与水平进行分类的方式之一。其中，C表示干系人当前参与程度，D表示所需王系人参与程度（P512）　<span class="quiz-src">2023 年下半年高项第 2 批</span></p></details><p><a id="q77" class="quiz-anchor"></a></p><p><strong>77.</strong> （ ）用于对干系人信息、相互关系以及他们与组织的关系进行可视化整理</p><ul><li>A．思维导图</li><li>B．干系人参与度评估矩阵</li><li>C．根本原因分析</li><li>D．优先级排序或分级</li></ul><details class="quiz" data-q="77" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：512。思维导图：用于对王系人信息、相互关系以及他们与组织的关系进行可视化整理　<span class="quiz-src">2023 年下半年高项第 2 批</span></p></details><p><a id="q78" class="quiz-anchor"></a></p><p><strong>78.</strong> 某项目经理在编制干系人管理计划，绘制的如下表格是（ ）。表格按干系人列示其在「不知晓／抵制／支持／领导」四档上的当前状态与期望状态。</p><ul><li>A．干系人职责分配矩阵</li><li>B．干系人优先矩阵</li><li>C．干系人参与度评估矩阵</li><li>D．干系人亲和图</li></ul><details class="quiz" data-q="78" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：王系人参与度评估知阵：用于将干系人当前参与水平与期望参与水平进行比较。对干系人参与水平进行分类的方式之二。其中，C表示干系人当前参与程度，D表示所需干系人参与程度（P512）　<span class="quiz-src">2023 年下半年高项第 3 批</span></p></details><p><a id="q79" class="quiz-anchor"></a></p><p><strong>79.</strong> 关于干系人管理，正确的是（ ）。</p><ul><li>A．干系人参与计划必须是正式的、详细的项目文件，以确保满足项目的需要</li><li>B．规划干系人参与过程是管理干系人参与过程的前置流程，不受管理干系人参与过程的影响</li><li>C．管理干系人参与过程的输出包括变更请求、组织过程资产、事业环境因素</li><li>D．管理干系人参与过程的主要作用是尽可能提高干系人的支持度、降低抵制程度</li></ul><details class="quiz" data-q="79" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：A不正确，所有的管理计划都可以是正式的，也可以是非正式的。B不正确，规划干系人参与过程需要定期开展，需要根据干系人管理的其它过程反馈来不断地调整计划（P509-512）　<span class="quiz-src">2024 年高项第 1 批</span></p></details><p><a id="q80" class="quiz-anchor"></a></p><p><strong>80.</strong> 项目经理根据干系人的需求、期望、利益和对项目的潜在影响，制定项目干系人参与项目的方法，则该项目经理正在执行（ ）过程。</p><ul><li>A．规划干系人参与</li><li>B．识别干系人</li><li>C．管理干系人参与</li><li>D．监督干系人参与</li></ul><details class="quiz" data-q="80" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：规划干系人参与是根据干系人的需求、期望、利益和对项目的潜在影响，制定项目干系人参与项目的方法的过程（P509）　<span class="quiz-src">2024 年高项第 2 批</span></p></details><p><a id="q81" class="quiz-anchor"></a></p><p><strong>81.</strong> 关于干系人参与计划的描述，不正确的是（ ）。</p><ul><li>A．干系人参与计划是项目管理计划的组成部分</li><li>B．干系人参与计划基于项目的需要和干系人的期望而制定</li><li>C．干系人参与计划是识别干系人过程的输出</li><li>D．干系人参与计划制订了干系人有效参与和执行项目决策的策略和行动</li></ul><details class="quiz" data-q="81" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：王系人参与计划是规划干系人参与过程的输出（P512）　<span class="quiz-src">2024 年高项第 2 批</span></p></details><p><a id="q82" class="quiz-anchor"></a></p><p><strong>82.</strong> 以下（ ）工具用于比较干系人的当前参与水平与期望参与水平。</p><ul><li>A．权力/利益矩阵</li><li>B．职责分配矩阵</li><li>C．概率和影响矩阵</li><li>D．干系人参与度评估矩阵</li></ul><details class="quiz" data-q="82" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：王系人参与度评估矩阵：用于将干系人当前参与水平与期望参与水平进行比较（P512）　<span class="quiz-src">2025 年高项第 1 批</span></p></details><p><a id="q83" class="quiz-anchor"></a></p><p><strong>83.</strong> 规划干系人参与过程的输入不包括（ ）。</p><ul><li>A．干系人登记册</li><li>B．项目进度计划</li><li>C．问题日志</li><li>D．干系人参与计划</li></ul><details class="quiz" data-q="83" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：干系人参与计划是规划干系人参与过程的输出（P512）　<span class="quiz-src">2026 年高项第 1 批</span></p></details><p><a id="q84" class="quiz-anchor"></a></p><p><strong>84.</strong> （ ）是通过与干系人进行沟通协作，以满足其需求与期望、处理问题，并促进干系人合理参与的过程。</p><ul><li>A．识别干系人</li><li>B．规划干系人参与i</li><li>C．管理干系人参与</li><li>D．监督干系人参与</li></ul><details class="quiz" data-q="84" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：管理干系人参与是通过与干系人进行沟通协作，以满足其需求与期望、处理问题，并促进王系人合理参与的过程（P512）　<span class="quiz-src">自编</span></p></details><p><a id="q85" class="quiz-anchor"></a></p><p><strong>85.</strong> （ ）过程的主要作用之一是，尽可能提高干系人的支持度，并降低干系人的抵制程度</p><ul><li>A．识别干系人</li><li>B．规划干系人参与</li><li>C．管理干系人参与</li><li>D．监督干系人参与</li></ul><details class="quiz" data-q="85" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：管理干系人参与：尽可能提高干系人的支持度，并降低干系人的抵制程度（P512）　<span class="quiz-src">自编</span></p></details><p><a id="q86" class="quiz-anchor"></a></p><p><strong>86.</strong> 管理干系人参与过程是通过与干系人进行（ ），以满足其需求与期望、处理问题，并促进干系人合理参与的过程；其作用是尽可能提高干系人的（ ），并降低其（ ）。</p><ul><li>A．沟通协作、支持度、抵制程度</li><li>B．谈判协商、抵制程度、支持度</li><li>C．谈判协商、支持度、抵制程度</li><li>D．沟通协作、抵制程度、支持度</li></ul><details class="quiz" data-q="86" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：管理干系人参与是通过与干系人进行沟通协作，以满足其需求与期望、处理问题，并促进王系人合理参与的过程。本过程的主要作用是，尽可能提高王系人的支持度，并降低干系人的抵制程度（P512）　<span class="quiz-src">自编</span></p></details><p><a id="q87" class="quiz-anchor"></a></p><p><strong>87.</strong> 引导干系人参与，以便获取、确认或维持他们对项目成功的持续承诺，属于干系人管理中的哪个过程的活动（ ）。</p><ul><li>A．识别干系人</li><li>B．规划干系人参与</li><li>C．管理干系人参与</li><li>D．监督干系人参与</li></ul><details class="quiz" data-q="87" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：在管理干系人参与过程中，需要开展多项活动，包括：①在适当的项目阶段引导王系人参与，以便获取、确认或维持他们对项目成功的持续承谐；②通过谈判和沟通的方式管理王系人期望③处理与干系人管理有关的任何风险或潜在关注点，预测干系人可能在未来引发的问题；④设酒和解决已识别的问题等（P513）　<span class="quiz-src">自编</span></p></details><p><a id="q88" class="quiz-anchor"></a></p><p><strong>88.</strong> 处理与干系人管理有关的风险或潜在关注点，预测干系人可能引发的问题，属于干系人管理中的哪个过程的活动（ ）。</p><ul><li>A．识别干系人</li><li>B．规划干系人参与i</li><li>C．管理干系人参与</li><li>D．监督干系人参与</li></ul><details class="quiz" data-q="88" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：在管理干系人参与过程中，需要开展多项活动，包括：①在适当的项目阶段引导王系人参与以便获取、确认或维持他们对项目成功的持续承谐；②通过谈判和沟通的方式管理干系人期望③处理与干系人管理有关的任何风险成潜在关注点，预测干系人可能在未来引发的问题；④澄酒和解决已识别的问题等（P513）　<span class="quiz-src">自编</span></p></details><p><a id="q89" class="quiz-anchor"></a></p><p><strong>89.</strong> 在管理干系人参与过程中，需要开展多项活动，下面哪个不属于管理干系人参与的活动（ ）</p><ul><li>A．澄清和解决已识别的问题</li><li>B．通过谈判和沟通的方式管理干系人期望</li><li>C．处理与干系人管理有关的风险或潜在关注点，预测干系人可能引发的问题</li><li>D．调整与干系人的沟通频率和沟通方法，以便更好地管理干系人</li></ul><details class="quiz" data-q="89" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：在管理干系人参与过程中，需要开展多项活动，包括：①在适当的项目阶段引导王系人参与以便获取、确认或维持他们对项目成功的持续承诺；②通过谈判和沟通的方式管理干系人期望③处理与干系人管理有关的任何风险或潜在关注点，预测干系人可能在未来引发的问题；④澄清和解决已识别的问题等（P513）　<span class="quiz-src">自编</span></p></details><p><a id="q90" class="quiz-anchor"></a></p><p><strong>90.</strong> （ ）有助于项目经理和团队通过考虑文化差异和干系人需求。</p><ul><li>A．冲突管理</li><li>B．文化意识</li><li>C．谈判</li><li>D．观察和交谈</li></ul><details class="quiz" data-q="90" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：冲突管理：项目经理应确保及时解决冲突。●文化意识：有助于项目经理和团队通过考虑文化差异和干系人需求。●谈判：用于获得支持或达成关于支持项目工作或成果的协议（P514）　<span class="quiz-src">自编</span></p></details><p><a id="q91" class="quiz-anchor"></a></p><p><strong>91.</strong> （ ）及时了解项目团队成员和其他干系人的工作和态度。</p><ul><li>A．冲突管理</li><li>B．文化意识</li><li>C．谈判</li><li>D．观察和交谈</li></ul><details class="quiz" data-q="91" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：冲突管理：项目经理应确保及时解决冲突。●文化意识：有助于项目经理和团队通过考虑文化差异和干系人需求●谈判：用于获得支持或达成关于支持项目工作或成果的协议●观察和交谈：及时了解项目团队成员和其他干系人的工作和态度（P514）　<span class="quiz-src">自编</span></p></details><p><a id="q92" class="quiz-anchor"></a></p><p><strong>92.</strong> （ ）是管理干系人参与过程的人际关系与团队技能之一，可用于获得支持或达成关于支持项目工作或成果的协议，并解决团队内部或团队与其他干系人之间的冲突。</p><ul><li>A．文化意识</li><li>B．谈判</li><li>C．冲突管理</li><li>D．观察和交谈</li></ul><details class="quiz" data-q="92" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：适用于管理干系人参与过程的人际关系与团队技能主要包括：●冲突管理：项目经理应确保及时解决冲突，●文化意识：有助于项目经理和团队通过考虑文化差异和干系人需求，来实现有效沟通●谈判：用于获得支持或达成关于支持项目工作成成果的协议，并解决团队内部或团队与其他干系人之间的冲突（P514）　<span class="quiz-src">自编</span></p></details><p><a id="q93" class="quiz-anchor"></a></p><p><strong>93.</strong> 在管理干系人参与中需要更新的项目文件不包括（ ）。</p><ul><li>A．变更日志</li><li>B．问题日志</li><li>C．干系人参与计划</li><li>D．干系人登记册</li></ul><details class="quiz" data-q="93" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：干系人参与计划是项目管理计划，不是项目文件。可在管理干系人参与过程更新的项目文件主要包括：变更日志、问题日志、经验教训登记册王系人登记册（P515）　<span class="quiz-src">自编</span></p></details><p><a id="q94" class="quiz-anchor"></a></p><p><strong>94.</strong> 随着项目的开展，项目周会的出席人数一直在下降，如果要鼓励干系人积极参加，项目经理应该查阅（ ）。</p><ul><li>A．干系人登记册</li><li>B．沟通管理计划</li><li>C．人力资源管理计划</li><li>D．干系人参与计划</li></ul><details class="quiz" data-q="94" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：正确项为「干系人参与计划」，原解析未给课本依据　<span class="quiz-src">自编</span></p></details><p><a id="q95" class="quiz-anchor"></a></p><p><strong>95.</strong> 在需求调研完毕后，项目经理小张，举行一场需求评审会，邀请到了客户代表来参加，这属于（ ）。</p><ul><li>A．识别干系人</li><li>B．规划干系人参与j</li><li>C．管理干系人参与</li><li>D．监督干系人参与</li></ul><details class="quiz" data-q="95" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：正确项为「管理干系人参与」，原解析未给课本依据　<span class="quiz-src">自编</span></p></details><p><a id="q96" class="quiz-anchor"></a></p><p><strong>96.</strong> 在管理干系人参与过程中，通过（ ）方式管理干系人期望。</p><ul><li>A．鼓舞和激励</li><li>B．表扬和引导</li><li>C．谈判和沟通</li><li>D．澄清和解决</li></ul><details class="quiz" data-q="96" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：在管理干系人参与过程中，需要开展多项活动，包括：①在适当的项目阶段引导王系人参与以便获取、确认或维持他们对项目成功的持续承诺；②通过谈判和沟通的方式管理干系人期望③处理与干系人管理有关的任何风险或潜在关注点，预测干系人可能在未来引发的问题；④海洁和解决已识别的问题等（P513）　<span class="quiz-src">2024 年中项第 2 批</span></p></details><p><a id="q97" class="quiz-anchor"></a></p><p><strong>97.</strong> 管理干系人参与过程的输入，不包含（ ）。</p><ul><li>A．干系人参与计划</li><li>B．变更请求</li><li>C．干系人登记册</li><li>D．变更管理计划</li></ul><details class="quiz" data-q="97" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：513-514,B属于输出。管理王系人参与过程的输入：1.项目管理计划（沟通管理计划、风险管理计划、干系人参与计划、变更管理计划）2.项目文件（问题日志、干系人登记册、变更日志、经验教训登记册）3.事业环境因素4.组织过程资产　<span class="quiz-src">2025 年中项第 1 批</span></p></details><p><a id="q98" class="quiz-anchor"></a></p><p><strong>98.</strong> （ ）不属于管理干系人参与的活动。</p><ul><li>A．引导干系人参与</li><li>B．提供与干系人沟通计划</li><li>C．通过谈判和沟通的方式管理干系人期望</li><li>D．澄清和解决已识别的问题</li></ul><details class="quiz" data-q="98" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：在管理干系人参与过程中，需要开展多项活动，包括：●在适当的项目阶段引导干系人参与，以便获取、确认或维持他们对项目成功的持续承诺：●通过谈判和沟通的方式管理干系人期望；处理与干系人管理有关的任何风险或潜在关注点，预测干系人可能在未来引发的问题；●澄清和解决已识别的问题等（P513）　<span class="quiz-src">2025 年中项第 4 批</span></p></details><p><a id="q99" class="quiz-anchor"></a></p><p><strong>99.</strong> 管理干系人参与过程的主要活动不包括（ ）。</p><ul><li>A．处理与干系人管理有关的任何风险或潜在关注点</li><li>B．引导干系人参与，维持其对项目成功的承诺</li><li>C．通过谈判和沟通管理干系人期望</li><li>D．识别干系人，更新干系人登记册</li></ul><details class="quiz" data-q="99" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：在管理干系人参与过程中，需要开展多项活动，包括：一在适当的项目阶段引导干系人参与，以便获取、确认或维持他们对项目成功的持续承诺：·通过谈判和沟通的方式管理干系人期望；一处理与干系人管理有关的任何风险或潜在关注点，预测干系人可能在未来引发的问题；一澄清和解决已识别的问题等（P513）　<span class="quiz-src">2026 年上半年中项第 1 批</span></p></details><p><a id="q100" class="quiz-anchor"></a></p><p><strong>100.</strong> A公司承接了某银行网上银行系统的建设项目，包括应用软件开发、软硬件集成适配、系统运维等多项工作内容。针对该项目，不正确的是（ ）。</p><ul><li>A．该项目的干系人包括客户、公司高层领导、项目成员及网上银行用户</li><li>B．干系人管理工作应由该项目成员分工负责</li><li>C．干系人管理有助于为项目赢得更多的资源</li><li>D．通常来说，干系人对项目的影响能力在项目启动阶段最大，随着项目的进展逐渐减羽</li></ul><details class="quiz" data-q="100" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：选项A正确：银行网上银行系统项目的干系人范围覆盖全面，客户、A公司高层领导、项目成员、网上银行用户均属于关键干系人；选项B错误：干系人管理的核心责任主体是项目经理，而非项目成员分工负责　<span class="quiz-src">2018 年上半年高项</span></p></details><p><a id="q101" class="quiz-anchor"></a></p><p><strong>101.</strong> 以下关于干系人管理过程的作用不正确的是（ ）。</p><ul><li>A．识别干系人过程的主要作用是，使项目团队能够建立对每个干系人或干系人群体的适度关注</li><li>B．规划干系人参与过程的主要作用是，提供与干系人进行有效互动的可行计划</li><li>C．管理干系人参与过程的主要作用是，及时向干系人提供相关信息，引导干系人有效参与项目</li><li>D．监督干系人参与过程的主要作用是，随着项目进展和环境变化，维持或提升干系人参与活动的效率和效果</li></ul><details class="quiz" data-q="101" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：管理干系人参与过程的主要作用是，尽可能提高王系人的支持度，并降低干系人的抵制程度（P512）　<span class="quiz-src">2023 年下半年高项第 2 批</span></p></details><p><a id="q102" class="quiz-anchor"></a></p><p><strong>102.</strong> 关于管理干系人参与过程的描述，正确的是（ ）。</p><ul><li>A．管理干系人参与的活动包括预测，澄清和解决干系人可能在未来引发的问题</li><li>B．管理干系人参与的主要作用是维持或提升干系人参与活动的效率和效果</li><li>C．管理干系人参与有助于干系人明确了解项目的目的、目标、收益和风险</li><li>D．沟通管理计划可作为管理干系人参与过程输入，被纳入项目文件进行管理</li></ul><details class="quiz" data-q="102" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：B不正确。P515。监督干系人参与是监督项目干系人的关系，并通过修订参与策略和计划来引导干系人合理参与项目的过程。本过程的主要作用是，随着项目进展和环境变化，维持或提升干系人参与活动的效率和效果（P513-515）　<span class="quiz-src">2025 年高项第 2 批</span></p></details><p><a id="q103" class="quiz-anchor"></a></p><p><strong>103.</strong> 管理干系人参与”过程用到的项目管理计划组件不包括（ ）。</p><ul><li>A．沟通管理计划</li><li>B．风险管理计划</li><li>C．进度计划</li><li>D．变更管理计划</li></ul><details class="quiz" data-q="103" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：进度计划属于项目文件。可用于管理干系人参与的项目管理计划组件主要包括●沟通管理计划：描述与干系人沟通的方法、形式和技术（P513）　<span class="quiz-src">2026 年高项第 2 批</span></p></details><p><a id="q104" class="quiz-anchor"></a></p><p><strong>104.</strong> 监督干系人参与过程的作用是（ ）。</p><ul><li>A．维持或提升干系人参与活动的效率和效果</li><li>B．提高干系人对项目的支持度，并尽可能降低干系人对项目的抵制</li><li>C．提供与干系人进行有效互动的可行计划</li><li>D．项目团队能够建立对每个干系人或干系人群体的适度关注</li></ul><details class="quiz" data-q="104" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：监督干系人参与：随着项目进展和环境变化，维持或提升干系人参与活动的效率和效果（P515）　<span class="quiz-src">教材第 17 章章节习题</span></p></details><p><a id="q105" class="quiz-anchor"></a></p><p><strong>105.</strong> 关于管理干系人参与过程的活动、工具及作用，不正确的是（ ）。</p><ul><li>A．管理干系人参与的活动包括引导干系人参与，预测干系人可能在未来引发的问题</li><li>B．冲突管理、谈判、观察和交谈均属于管理干系人参与的人际关系与团队技能</li><li>C．管理干系人参与的主要作用是维持或提升干系人参与活动的效率和效果</li><li>D．文化意识有助于项目经理和团队考虑文化差异，更好地开展干系人参与管理</li></ul><details class="quiz" data-q="105" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：监督干系人参与是监督项目干系人的关系，并通过修订参与策略和计划来引导干系人合理参与项目的过程。本过程的主要作用是，随着项目进展和环境变化，维持或提升干系人参与活动的效率和效果，C描述不正确（P515）　<span class="quiz-src">自编</span></p></details><p><a id="q106" class="quiz-anchor"></a></p><p><strong>106.</strong> 在监督干系人参与的时候，（ ）确定干系人群体和个人在项目任何特定时间的状态。</p><ul><li>A．备选方案分析</li><li>B．根本原因分析</li><li>C．干系人分析</li><li>D．多标准决策分析</li></ul><details class="quiz" data-q="106" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：备选方案分析：在干系人参与效果没有达到期望要求时，应该开展备选方案分析，评估应对偏差的各种备选方案。●根本原因分析：开展根本原因分析，确定干系人参与未达预期效果的根本原因（P516-517）　<span class="quiz-src">自编</span></p></details><p><a id="q107" class="quiz-anchor"></a></p><p><strong>107.</strong> （ ）考察干系人成功参与项目的标准，识别出最适当的选项。</p><ul><li>A．备选方案分析</li><li>B．根本原因分析</li><li>C．干系人分析</li><li>D．多标准决策分析</li></ul><details class="quiz" data-q="107" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：备选方案分析：在干系人参与效果没有达到期望要求时，应该开展备选方案分析，评估应对偏差的各种备选方案，●根本原因分析：开展根本原因分析，确定干系人参与未达预期效果的根本原因●干系人分析：确定干系人群体和个人在项目任何特定时间的状态●多标准决策分析：考察干系人成功参与项目的标准，识别出最适当的选项（P516-517）　<span class="quiz-src">自编</span></p></details><p><a id="q108" class="quiz-anchor"></a></p><p><strong>108.</strong> 以下不属于监督干系人参与的输出的是（ ）。</p><ul><li>A．哪些干系人支持项目</li><li>B．干系人参与状态有关的信息</li><li>C．干系人对项目的当前支持水平</li><li>D．与期望参与水平相比较的结果</li></ul><details class="quiz" data-q="108" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：P516。工作绩效数据包含项目状态数据，如哪些干系人支持项目，他们的参与水平和类型P517。工作绩效信息包括与干系人参与状态有关的信息，例如，干系人对项目的当前支持水平，以及与干系人参与度评估矩阵、干系人立方体或其他工具所确定的期望参与水平相比较的结果（P516-517）　<span class="quiz-src">自编</span></p></details><p><a id="q109" class="quiz-anchor"></a></p><p><strong>109.</strong> 使用（ ）来跟踪每个干系人参与水平的变化，对干系人参与加以监督。</p><ul><li>A．干系人分析</li><li>B．备选方案分析</li><li>C．干系人参与计划</li><li>D．干系人参与度评估矩阵</li></ul><details class="quiz" data-q="109" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：适用于监督干系人参与过程的数据表现技术主要是干系人参与度评估矩阵。使用王系人参与度评估矩阵来跟踪每个干系人参与水平的变化，对干系人参与加以监督（P517）　<span class="quiz-src">自编</span></p></details><p><a id="q110" class="quiz-anchor"></a></p><p><strong>110.</strong> 以下不属于监督干系人参与过程的人际关系与团队技能的是（ ）。</p><ul><li>A．积极倾听</li><li>B．文化意识</li><li>C．人际交往</li><li>D．反馈</li></ul><details class="quiz" data-q="110" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：适用于监督干系人参与过程的人际关系技能主要包括：●积极倾听：通过积极倾听，减少理解错误和沟通错误。●文化意迟：文化意识和文化敏感性有助于项目经理分析干系人和团队成员的文化差异和文化需求，并对沟通进行规划（P517）　<span class="quiz-src">自编</span></p></details><p><a id="q111" class="quiz-anchor"></a></p><p><strong>111.</strong> （ ）用于确保发送给干系人的信息被接收和理解。</p><ul><li>A．反馈</li><li>B．演示</li><li>C．积极倾听</li><li>D．领导力</li></ul><details class="quiz" data-q="111" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：反馈：用于确保发送给王系人的信息被接收和理解。演示：为王系人提供清晰的信息（P517）　<span class="quiz-src">自编</span></p></details><p><a id="q112" class="quiz-anchor"></a></p><p><strong>112.</strong> 在监督干系人参与过程中，（ ）减少理解错误和沟通错误。</p><ul><li>A．反馈</li><li>B．演示</li><li>C．积极倾听</li><li>D．领导力</li></ul><details class="quiz" data-q="112" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：积极倾听：通过积极顿听，减少理解错误和沟通错误（P517）　<span class="quiz-src">自编</span></p></details><p><a id="q113" class="quiz-anchor"></a></p><p><strong>113.</strong> 适用于监督干系人参与过程的数据表现技术主要是（ ）。</p><ul><li>A．干系人参与度评估矩阵</li><li>B．思维导图</li><li>C．龙卷风图</li><li>D．直方图</li></ul><details class="quiz" data-q="113" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：适用于监督干系人参与过程的数据表现技术主要是干系人参与度评估矩陛（P517）　<span class="quiz-src">自编</span></p></details><p><a id="q114" class="quiz-anchor"></a></p><p><strong>114.</strong> 在监督干系人参与过程中，（ ）传递愿景并激励干系人支持项目工作和成果。</p><ul><li>A．反馈</li><li>B．演示</li><li>C．积极倾听</li><li>D．领导力</li></ul><details class="quiz" data-q="114" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：成功的干系人参与，需要强有力的领导技能，以传递愿量并激励干系人支持项目工作和成果（P517）　<span class="quiz-src">自编</span></p></details><p><a id="q115" class="quiz-anchor"></a></p><p><strong>115.</strong> 在监督干系人参与过程中，（ ）有助于理解组织战略，理解谁能行使权力和施加影响，以及培养与这些干系人沟通的能力。</p><ul><li>A．积极倾听</li><li>B．文化意识</li><li>C．人际交往</li><li>D．政策意识</li></ul><details class="quiz" data-q="115" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：政策意识：有助于理解组织战略，理解谁能行使权力和施加影响，以及培养与这些干系人沟通的能力（P517）　<span class="quiz-src">自编</span></p></details><p><a id="q116" class="quiz-anchor"></a></p><p><strong>116.</strong> 以下属于监督干系人参与过程输出的工作绩效信息的是（ ）。</p><ul><li>A．干系人对项目的当前支持水平</li><li>B．干系人身份信息</li><li>C．干系人分类</li><li>D．干系人参与度评估矩阵</li></ul><details class="quiz" data-q="116" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：工作绩效信息包括与干系人参与状态有关的信息，例如，干系人对项目的当前支持水平，以及与干系人参与度评估矩阵、干系人立方体或其他工具所确定的期望参与水平相比较的结果（P517）　<span class="quiz-src">自编</span></p></details><p><a id="q117" class="quiz-anchor"></a></p><p><strong>117.</strong> 在项目进行一段时间后，项目经理蜗牛老师发现总部调来的技术专家业务繁忙，总是不能及时地参加我们的技术交流会。为此蜗牛老师在和技术专家进行深入沟通后，约定了每次参会时间由原来的1小时改成30分钟，并且专家只需要来间答问题，不用准备课题，随后蜗牛老师更改了沟通管理计划和干系人参与计划，这属于（ ）。</p><ul><li>A．识别干系人</li><li>B．规划干系人参与</li><li>C．管理干系人参与</li><li>D．监督干系人参与i</li></ul><details class="quiz" data-q="117" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：正确项为「监督干系人参与i」，原解析未给课本依据　<span class="quiz-src">自编</span></p></details><p><a id="q118" class="quiz-anchor"></a></p><p><strong>118.</strong> 在干系人管理过程中，（ ）不是监督干系人参与过程的输入。</p><ul><li>A．资源管理计划</li><li>B．问题日志</li><li>C．工作绩效信息</li><li>D．项目沟通记录</li></ul><details class="quiz" data-q="118" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：工作绩效信息属于输出，监督干系人参与的主要输入：1项目管理计划（沟通管理计划、风险管理计划、干系人参与计划、变更管理计划）2.项目文件（问题日志、干系人登记册、变更日志、经验教训登记册）3事业环境因素；4.组织过程资产（P516）　<span class="quiz-src">2024 年中项第 3 批</span></p></details><p><a id="q119" class="quiz-anchor"></a></p><p><strong>119.</strong> 执行阶段需要定期评估干系人支持程度并调整干系人管理策略。项目经理使用（ ）可以跟踪支持水平的变化。</p><ul><li>A．干系人立方体</li><li>B．权力利益方格</li><li>C．影响方向分类</li><li>D．干系人参与度评估矩阵</li></ul><details class="quiz" data-q="119" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：适用于监督干系人参与过程的数据表现技术主要是干系人参与度评估知阵。使用干系人参与度评估矩阵来跟踪每个干系人参与水平的变化，对干系人参与加以监督（P517）　<span class="quiz-src">2025 年中项第 2 批</span></p></details><p><a id="q120" class="quiz-anchor"></a></p><p><strong>120.</strong> A公司正在给B公司做一个运维管理体系咨询项目，小张作为B公司的项目接口人，主要完成两家公司间的资料传递工作。但最近A公司提交的文档经常出现问题，小张经常受到批评，因此B公司的项目经理要求小张做资料初审工作。针对这一变化情况，A公司的项目经理在干系人管理上应该做（ ）。①更新干系人联系手册；②更新项目管理计划；③形成问题日志；④填写变更请求；⑤修改项目章程</p><ul><li>A．①②③</li><li>B．45</li><li>C．②④⑤</li><li>D．①②④</li></ul><details class="quiz" data-q="120" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：首先肯定有问题日志，这样CD就排除掉了。然后B里面修改项目章程明显错误，所以答案选A。【蜗牛老师点评】这种场景题有的时候答案并不是很明确，用排除法来做才是最好的　<span class="quiz-src">2018 年下半年高项</span></p></details><p><a id="q121" class="quiz-anchor"></a></p><p><strong>121.</strong> 随着项目进展和环境变化，维持或提升干系人参与活动的效率和效果，属于（ ）</p><ul><li>A．识别干系人</li><li>B．规划干系人参与(</li><li>C．管理干系人参与</li><li>D．监督干系人参与</li></ul><details class="quiz" data-q="121" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：监督干系人参与是监督项目干系人的关系，并通过修订参与策略和计划来引导干系人合理参与项目的过程。主要作用是随着项目进展和环境变化，维持成提升干系人参与活动的效率和效果（P515）　<span class="quiz-src">2023 年下半年高项第 2 批</span></p></details><p><a id="q122" class="quiz-anchor"></a></p><p><strong>122.</strong> 适用于监督干系人参与过程的数据表现技术是（ ）。</p><ul><li>A．沟通技能</li><li>B．根本原因分析</li><li>C．干系人参与度评估矩阵</li><li>D．干系人分析技术</li></ul><details class="quiz" data-q="122" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：适用于监督王系人参与过程的数据表现技术主要是王系人参与度评估矩陛（P517）　<span class="quiz-src">2023 年下半年高项第 4 批</span></p></details><p><a id="q123" class="quiz-anchor"></a></p><p><strong>123.</strong> 监督干系人参与时，（ ）用于确定干系人群体和个人在项目任何特定时间的状态。</p><ul><li>A．根本原因分析</li><li>B．优先级排序</li><li>C．职责分配矩阵</li><li>D．干系人分析</li></ul><details class="quiz" data-q="123" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：适用于监督干系人参与过程的数据分析技术主要包括：●备选方案分析：在干系人参与效果没有达到期望要求时，应该开展备选方案分析，评估应对偏差的各种备选方案（P516）　<span class="quiz-src">2024 年高项第 2 批</span></p></details><p><a id="q124" class="quiz-anchor"></a></p><p><strong>124.</strong> （ ）不属于“监督干系人参与”过程的主要输出。</p><ul><li>A．干系人登记册</li><li>B．项目沟通记录</li><li>C．变更请求</li><li>D．风险登记册</li></ul><details class="quiz" data-q="124" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：监督干系人参与的主要输出：1工作绩效信息；2变更请求；3项目管理计划更新（资源管理计划、沟通管理计划、干系人参与计划）;4.项目文件更新（问题日志、经验教训登记册、风险登记册、干系人登记册）（P517）　<span class="quiz-src">2025 年高项第 1 批</span></p></details><p><a id="q125" class="quiz-anchor"></a></p><p><strong>125.</strong> 监督干系人参与”的主要工作是（ ）。</p><ul><li>A．采用适当的技术和方法与干系人沟通形成沟通记录</li><li>B．基于干系人参与状态，分析偏差并采取纠正措施</li><li>C．识别新增的项目干系人，更新干系人登记册</li><li>D．制定具体的干系人参与策略和计划</li></ul><details class="quiz" data-q="125" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：监督干系人参与是监督项目干系人的关系，并通过修订参与策略和计划来引导干系人合理参与项目的过程。本过程的主要作用是，随着项目进展和环境变化，维持或提升干系人参与活动的效率和效果（P515）　<span class="quiz-src">2026 年高项第 1 批</span></p></details></div>`,1)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};